<?php
declare(strict_types=1);
$env=[];foreach(file(__DIR__.'/../.env',FILE_IGNORE_NEW_LINES|FILE_SKIP_EMPTY_LINES)?:[] as $line){$line=trim($line);if($line===''||$line[0]==='#'||!str_contains($line,'='))continue;[$k,$v]=explode('=',$line,2);$env[trim($k)]=trim(trim($v),"\"'");}
$p=new PDO('mysql:host='.$env['GPT_DB_HOST'].';port='.$env['GPT_DB_PORT'].';dbname=gatlas_dbp;charset=utf8mb4',$env['GPT_DB_USERNAME'],$env['GPT_DB_PASSWORD'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);
foreach(['menusxconfiguracoes','nearmiss_nc_indicacao_ocorrencia'] as $table){$q=$p->prepare("SELECT column_name,is_nullable,column_default FROM information_schema.columns WHERE table_schema='gatlas_dbp' AND table_name=? AND column_type LIKE 'varchar(%' AND character_maximum_length>=1000");$q->execute([$table]);foreach($q as $c){$null=$c['IS_NULLABLE']==='NO'?' NOT NULL':' NULL';$p->exec('ALTER TABLE `'.$table.'` MODIFY `'.$c['COLUMN_NAME'].'` TEXT'.$null);}}
$p->exec("ALTER TABLE `pendencias_planodeacao` DROP INDEX `IPENDENCIAS_PLANODEACAO`");$p->exec("ALTER TABLE `pendencias_planodeacao` ENGINE=InnoDB, ROW_FORMAT=DYNAMIC, CONVERT TO CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci");$p->exec("ALTER TABLE `pendencias_planodeacao` ADD INDEX `IPENDENCIAS_PLANODEACAO` (`DSCUNIDADE`(191),`TIPO`(191),`NRANO`(191),`ETAPA`(191))");echo "ok\n";
